"""Offline review assembled only from current, verified scene and render hashes."""
from pathlib import Path
import json,hashlib,html,csv
from PIL import Image,ImageDraw
H=Path(__file__).resolve().parent;R=H.parent.parent
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
S=json.loads((H/'style.json').read_text());D=json.loads((H/'geometry.json').read_text());V=json.loads((H/'validation.json').read_text());G=json.loads((H/'geometry-validation.json').read_text());M=json.loads((H/'render-manifest.json').read_text());section=json.loads((H/'scene-section.json').read_text())
assert V['all_pass'] and G['all_pass']
assert V['blend_sha256']==M['blend_sha256']==sha(R/'models/section-2/section-2-finish.blend')
assert G['blend_sha256']==sha(R/'models/section-2/section-2-geometry.blend')
assert M['style_sha256']==sha(H/'style.json')
names=[c['name'] for c in S['cameras']]+['05-top']
for n in names:assert M['images'][n+'.png']==sha(H/'previews'/(n+'.png'))
# Reproducible technical overlay; the source file is only read.
im=Image.open(R/'plans/section-2-common-areas.png').convert('RGB');dr=ImageDraw.Draw(im)
for seg in section['segments']:dr.line([tuple(x) for x in seg['points']],fill=(0,100,255),width=2)
dr.rectangle((489,373,559,411),outline=(235,70,0),width=4);im.save(H/'previews/geometry-overlay.png')
desc=['Из тамбура через остеклённую дверь виден вестибюль. Указатель ведёт к лифту через эту дверь.','Открытая колясочная с общей поверхностью пола, защищённой стеной и одной коляской для масштаба.','Древесные акценты и ровный тёплый свет связывают коридор с лифтом.','Жилой вход, семь подъёмов и условный подъёмник. Соседний вход не включён в кадр.']
gallery=''.join(f'<figure><a href="previews/{c["name"]}.png"><img src="previews/{c["name"]}.png" width="1920" height="1280" alt="{html.escape(c["label"])}"></a><figcaption><span>0{i+1}</span><div><h2>{html.escape(c["label"])}</h2><p>{desc[i]}</p></div></figcaption></figure>' for i,c in enumerate(S['cameras']))
pal=''.join(f'<div><span style="background:{S["palette"][k]}"></span><b>{v}</b><small>{S["palette"][k]}</small></div>' for k,v in [('wall','Стены'),('floor','Камень'),('wood','Дерево'),('charcoal','Графит'),('entry_floor','Тамбур'),('contact','Защита стены')])
lines=''.join(f'<path d="M {v["points"][0][0]} {v["points"][0][1]} L {v["points"][1][0]} {v["points"][1][1]}"/>' for v in section['segments'])
W,HT=im.size
page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Секция 2 — отделка и свет</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f0e9;color:#302d29;font:16px/1.6 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}main{max-width:1440px;margin:auto;padding:40px 30px 70px}header{max-width:980px}.tag{font-size:12px;letter-spacing:.13em;text-transform:uppercase;color:#756953}h1{font:normal clamp(32px,5vw,58px)/1.13 Georgia,serif;margin:18px 0}p{color:#625c52}a{color:inherit;text-underline-offset:4px}nav{display:flex;gap:12px 25px;flex-wrap:wrap;margin:25px 0 38px}.gallery{display:grid;grid-template-columns:1fr 1fr;gap:24px}figure{margin:0;background:#fffdf9;border:1px solid #e2dbcf}figure img{display:block;width:100%;height:auto}figcaption{display:flex;gap:17px;padding:20px}figcaption>span{font-size:13px;color:#88775d}h2{font-size:18px;line-height:1.4;margin:0 0 6px}figcaption p{font-size:14px;margin:0}section{margin-top:48px}h3{font:normal 30px Georgia,serif;margin:0 0 22px}.split{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(240px,.6fr);gap:30px;align-items:start}.full{display:block;width:100%;height:auto}.note{background:#e9e3d8;padding:23px;border-left:4px solid #8b7355}.palette{display:grid;grid-template-columns:repeat(6,1fr);gap:14px}.palette span{display:block;height:80px;border:1px solid #d1c9bd}.palette b,.palette small{display:block;font-size:14px}.palette small{font-size:12px;color:#75695a}.source{background:white}.source svg{display:block;width:100%;height:auto}input{width:100%;accent-color:#0873b6}footer{margin-top:40px;border-top:1px solid #d6cdbc;padding-top:20px;font-size:14px}li{margin:8px 0}@media(max-width:800px){main{padding:26px 16px}.gallery,.split{grid-template-columns:1fr}.palette{grid-template-columns:repeat(3,1fr)}}
</style><main><header><div class="tag">Этап 4 · Концепция · Готово к общему показу</div><h1>Секция 2.<br>Отделка и свет</h1><p>Первый вариант в стилистике секции 1: светлые стены, бежевый камень, повторяющиеся древесные акценты и тёплый свет. Планировка и размеры взяты из собственных исходников секции 2.</p><nav><a href="#views">Четыре ракурса</a><a href="#top">Вид сверху</a><a href="#source">Сверка плана</a><a href="../../models/section-2/section-2-finish.blend">Сцена Blender</a></nav></header><div class="gallery" id="views">'''+gallery+'''</div><section id="top"><h3>Первый этаж сверху</h3><div class="split"><a href="previews/05-top.png"><img class="full" src="previews/05-top.png" alt="Цветной вид первого этажа секции 2 сверху"></a><aside><p>Тамбур, вестибюль с открытой колясочной, коридор и лифт сохраняют расположение по плану. Потолок находится на высоте 3 м без опуска.</p><div class="note"><b>Дверь после лестницы — на втором этаже</b><p>По вашему уточнению она размещена на +3,300. На этом виде она скрыта; направление подъёма обозначено стрелкой. Отдельного входа с крыльца в этой точке первого этажа нет.</p></div><p>Одна коляска показывает функцию и масштаб зоны, без утверждения вместимости.</p></aside></div></section><section><h3>Общая палитра</h3><div class="palette">'''+pal+'''</div><p>Цветовые ориентиры показаны без влияния света. <a href="materials.md">Материалы и места применения</a>.</p></section><section id="source"><h3>Сверка с утверждённым планом</h3><div class="split"><div class="source"><svg viewBox="0 0 '''+str(W)+' '+str(HT)+'''" aria-label="Исходный PNG и сечение построенных стен"><image href="../../plans/section-2-common-areas.png" width="'''+str(W)+'''" height="'''+str(HT)+'''"/><g id="mesh" fill="none" stroke="#0873e0" stroke-width="2">'''+lines+'''</g><rect x="489" y="373" width="70" height="38" fill="none" stroke="#dc6b26" stroke-width="4"/></svg></div><aside><label for="opacity">Видимость построенных стен</label><input id="opacity" type="range" min="0" max="1" step=".05" value="1"><p>Синие линии — сечение фактической модели на высоте 1,2 м. Оранжевым выделено согласованное уточнение уровня двери второго этажа.</p><p>Утверждённый PNG сохранён без изменений. Оценочные размеры и условные элементы перечислены в описании.</p><a href="previews/geometry-overlay.png">Открыть наложение</a></aside></div></section><footer><p>Пять изображений по 1920 пикселей по длинной стороне. Это комплект концепции для общего показа; окончательный рендер этапа 7 — не менее 2500 пикселей.</p><a href="README.md">Описание и проверки</a> · <a href="decisions.md">Принятые решения</a> · <a href="../../plans/section-2-common-areas.png">Исходный план</a></footer></main><script>document.getElementById('opacity').addEventListener('input',e=>{document.getElementById('mesh').style.opacity=e.target.value});</script></html>'''
(H/'review.html').write_text(page)
print('REVIEW_BUILT',len(names),'images')
